bg=6
patterns={1:[[0,0,1],[1,1,1],[0,0,1]],3:[[0,1,1],[0,1,1],[1,0,0]],7:[[0,1,1],[1,1,0],[0,0,1]],5:[[0,1,1],[1,1,0],[0,1,1]]}
# 0 means keep panel color, 1 means punch background
out=[[bg]*13 for _ in range(13)]
for rbase,cbase,color in [(1,1,1),(1,7,3),(7,1,7),(7,7,5)]:
    for r in range(5):
        for c in range(5): out[rbase+r][cbase+c]=color
    for r in range(3):
        for c in range(3):
            if patterns[color][r][c]: out[rbase+1+r][cbase+1+c]=bg
print('\n'.join(' '.join(map(str,row)) for row in out))
